using Xunit;

public class AlarmTest
{
    [Fact]
    public void HighLeakageAlarmTest()
    {
        // Arrange
        var averageLeakage = 4L;
        var threshold = 3L;

        // Act
        var alarm = new Alarm();
        alarm.ComputeHighLeakageAlarm(averageLeakage, threshold);

        // Assert
        Assert.True(alarm.IsHighLeakageAlarmActive);
    }

    [Fact]
    public void HighPriorityAlarmTest()
    {
        // Arrange
        var alarm = new Alarm();

        // Act
        alarm.SetHighPriorityAlarm();

        // Assert
        Assert.Equal(AlarmPriority.High, alarm.Priority);
    }

    [Fact]
    public void ContinuousToneAlarmTest()
    {
        // Arrange
        var alarm = new Alarm();

        // Act
        alarm.SetContinuousToneAlarm();

        // Assert
        Assert.True(alarm.IsContinuousToneAlarm);
    }

    [Fact]
    public void SoundToneDurationTest()
    {
        // Arrange
        var duration = 2.0;

        // Act
        var alarm = new Alarm();
        alarm.SetSoundToneDuration(duration);

        // Assert
        Assert.Equal(duration, alarm.SoundToneDuration);
    }

    [Fact]
    public void LossOfACMainsTest()
    {
        // Arrange
        var sensor = new ACMainsPowerLossSensor();
        sensor.DetectLossOfPower();

        // Act
        var alarm = new Alarm();
        alarm.DetectLossOfACMains(sensor);

        // Assert
        Assert.True(alarm.IsACMainsPowerLossAlarmActive);
    }

    [Fact]
    public void MediumPriorityAlarmTest()
    {
        // Arrange
        var alarm = new Alarm();

        // Act
        alarm.SetMediumPriorityAlarm();

        // Assert
        Assert.Equal(AlarmPriority.Medium, alarm.Priority);
    }
}
